"""Render the retrospective and prospectively frozen rejection-memory study from verified scores."""
from pathlib import Path

def page(w,read,table,links,fmt,preview):
    w.page("Отказы инструмента     /     ALFWorld","Нужно ли сохранять историю отказов",
           "Сравнили реакцию на последний отказ с запоминанием всех отклонённых направлений из текущей позиции.")
    w.p("На десяти проигранных играх 451 отказ пришёлся на две команды. Переход к третьему ящику был отклонён 282 раза, к третьей полке — 169. В одной игре агент безуспешно подошёл к одной полке 48 раз.")
    w.p("При отклике «Nothing happens.» первая политика исключает цель перехода на один шаг. Вторая сохраняет все отклонённые цели до успешной смены позиции. Обе используют исходный контроллер и одинаковые обучающие частоты.")
    if not preview:
        from rejection_outcomes import data
        data(w,read,table,fmt)
    w.p("Гипотезу сформировали по 134 играм valid_unseen. Для 140 других игр valid_seen правила зафиксированы до получения текстовых исходов. Их планировки были знакомы по прошлому опыту с меню.")
    w.h("Перенос на реальные команды кодового агента")
    w.p("В 53 380 действиях SWE-bench банк из восьми последних отказов без проверки актуальности дал 915 совпадений с повторной командой. Из них 462 реально завершились успешно. Если между совпадающими командами допускались только проверенные операции чтения, осталось 14 сигналов — десять точно повторили старый вывод и код ошибки, четыре привели к успеху. Хранение одного и восьми отказов дало те же решения. Аудит первичных сообщений установил таймаут в 11 из 14 исходных отказов, включая все четыре случая последующего успеха. Совпадение кода и вывода характеризует ответ оболочки. Метка отказа может служить поводом перепроверить состояние. Для автоматической блокировки команды требуется отдельное испытание.")
    links(("ALFWorld","https://github.com/alfworld/alfworld"),("Исторические траектории SWE-bench","https://github.com/SWE-bench/experiments/tree/40f164d5b8f1d249bf95a6df8b74b577fd8e519d/evaluation/verified"))

